% Andrii Kholod EDIfu25/2 20255272
% 1
x = -2:0.1:1 %[output:44ffca4a]
y = -2:0.1:1;
[X, Y] = meshgrid(x, y) %[output:11ec5a4e] %[output:6ded4b8e]

Z = 1 - 2*X.^2 - 3*Y.^2;
figure; %[output:6054cbcd]
surf(X, Y, Z); %[output:6054cbcd]
shading interp;      %[output:6054cbcd]
colormap('spring');     %[output:6054cbcd]

view(70, 30);        %[output:6054cbcd]

xlabel('X-axis'); %[output:6054cbcd]
ylabel('Y-axis'); %[output:6054cbcd]
zlabel('Z-axis'); %[output:6054cbcd]
title('Surface plot of f(x,y) = 1 - 2x^2 - 3y^2'); %[output:6054cbcd]
grid on; %[output:6054cbcd]

%2
x = (2*rand(1,200)-1).*sqrt(pi/2);
y = (2*rand(1,200)-1).*sqrt(pi/2);

x = sort(x);
y = sort(y);

[X, Y] = meshgrid(x, y);
Z = sin(X.^2 + Y.^2);

figure; %[output:6afed14d]
surf(X, Y, Z); %[output:6afed14d]

shading flat;        %[output:6afed14d]
colormap('winter');  %[output:6afed14d]

view(41, 30); %[output:6afed14d]

xlabel('X-axis'); %[output:6afed14d]
ylabel('Y-axis'); %[output:6afed14d]
zlabel('Z-axis'); %[output:6afed14d]
title('Surface plot of f(x,y) = sin(x^2 + y^2)'); %[output:6afed14d]
grid on; %[output:6afed14d]


%complementary
[X, Y] = meshgrid(-2:0.1:2, -2:0.1:2);

Z = 1 - (X.^2 + Y.^2);
figure('Name', 'Features of surf function', 'Position', [100, 100, 1200, 400]); %[output:48054b28]

subplot(1, 3, 1);        %[output:48054b28]
surf(X, Y, Z); %[output:48054b28]
shading interp;          %[output:48054b28]
h = camlight('left');        %[output:48054b28]
lighting gouraud;       %[output:48054b28]
title('a) camlight effect'); %[output:48054b28]
xlabel('X'); ylabel('Y'); zlabel('Z'); %[output:48054b28]
% for i = 1:36
%     camorbit(10, 0);
%     camlight(h, 'left'); 
%     drawnow; pause(0.125);
% end


subplot(1, 3, 2);        %[output:48054b28]
surfc(X, Y, Z);          %[output:48054b28]
shading interp; %[output:48054b28]
title('b) contour to main axis'); %[output:48054b28]
xlabel('X'); ylabel('Y'); zlabel('Z'); %[output:48054b28]


subplot(1, 3, 3);        %[output:48054b28]
surf(X, Y, Z); %[output:48054b28]
shading interp; %[output:48054b28]
alpha(0.6);              %[output:48054b28]
title('c) semitransparent surface'); %[output:48054b28]
xlabel('X'); ylabel('Y'); zlabel('Z'); %[output:48054b28]





